pub fn split_bill(total_cents: u32, people: u32) -> Vec<u32> {
    if people == 0 {
        panic!("split_bill needs at least one person, got 0");
    }
    let (share, extra) = (total_cents / people, total_cents % people);
    (0..people).map(|i| share + u32::from(i < extra)).collect()
}

pub fn parse_cents(text: &str) -> Result<u32, String> {
    let (dollars, cents) = text.split_once('.').ok_or(format!("{text:?} has no decimal point"))?;
    let d: u32 = dollars.parse().map_err(|e| format!("dollars: {e}"))?;
    let c: u32 = cents.parse().map_err(|e| format!("cents: {e}"))?;
    Ok(d * 100 + c)
}

